import hashlib, json, pathlib, sys
root=pathlib.Path('/home/saithat/Projects/VGI-Health')
out=pathlib.Path(__file__).parent
run=root/'runs/core-10day'
canonical=lambda value: json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
digest=lambda value:hashlib.sha256(value).hexdigest()
snapshot={'frozen':{},'decisions':{},'clinicalDays':{},'schedules':{}}
for p in sorted((run/'certifications').glob('P*/v*/*.json')):
 if p.name in ['spec.json','inputs.json']:snapshot['frozen'][str(p.relative_to(root))]=digest(canonical(json.loads(p.read_bytes())))
for p in sorted((run/'programs').glob('P*/v*.json')):
 if p.name.endswith('.components.json'):continue
 snapshot['frozen'][str(p.relative_to(root))]=digest(canonical(json.loads(p.read_bytes())))
for p in sorted((run/'decisions').glob('night-*/P*.json')):
 snapshot['decisions'][str(p.relative_to(root))]=digest(p.read_bytes())
manifest=json.loads((run/'manifest.json').read_bytes())
for p in sorted((run/'days').glob('day-*/P*.json')):
 d=json.loads(p.read_bytes())
 clinical={'day':d['day'],'persona':d['persona'],'programVersion':d['programVersion'],'tasks':[t['task'] for t in d['tasks']], 'trace':[{k:t[k] for k in ['task','event','screen','result'] if k in t} for t in d['trace']]}
 snapshot['clinicalDays'][str(p.relative_to(root))]={'sha256':digest(canonical(clinical)),'tasks':len(d['tasks']),'events':len(d['trace'])}
 world=pathlib.Path(manifest['world'])/'schedules'/p.parent.name/p.name
 snapshot['schedules'][str(world.relative_to(root))]=digest(world.read_bytes())
if sys.argv[1]=='before':
 (out/'integrity-before.json').write_bytes(canonical(snapshot)+b'\n')
 print({key:len(value) for key,value in snapshot.items()})
else:
 before=json.loads((out/'integrity-before.json').read_bytes())
 for key,value in snapshot.items():
  assert value==before[key], key+': changed entries '+str([p for p in set(value)|set(before[key]) if value.get(p)!=before[key].get(p)])
 report={'status':'pass','preserved':{key:len(value) for key,value in snapshot.items()},'tasks':sum(d['tasks'] for d in snapshot['clinicalDays'].values()),'events':sum(d['events'] for d in snapshot['clinicalDays'].values()),'snapshotSha256':digest(canonical(snapshot))}
 if sys.argv[1]=='after':(out/'integrity-after.json').write_bytes(canonical(report)+b'\n')
 print(json.dumps(report))

