import { writeFile } from 'node:fs/promises';
import assert from 'node:assert/strict';
const { chromium, expect } = await import(pathToFileURL(resolve('app/node_modules/@playwright/test/index.mjs')));
const server=spawn(process.execPath,[resolve('app/node_modules/vite/bin/vite.js'),'preview','--host','127.0.0.1','--port','4187','--strictPort'],{cwd:resolve('app'),stdio:['ignore','pipe','pipe']});
let log='';server.stdout.on('data',d=>log+=d);server.stderr.on('data',d=>log+=d);
let browser;
try {
 let ready=false;
 for(let i=0;i<200;i++){if(server.exitCode!==null)throw Error(log);try{if((await fetch('http://127.0.0.1:4187/screen-check.html')).ok){ready=true;break;}}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(ready,log);
 browser=await chromium.launch();
 const page=await browser.newPage({viewport:{width:1440,height:900},locale:'en-US',timezoneId:'America/Los_Angeles',reducedMotion:'reduce',colorScheme:'light'});
 const errors=[];page.on('pageerror',error=>errors.push(error.message));
 await page.goto('http://127.0.0.1:4187/dashboard?run=core-10day&persona=P3&view=Trajectories');
 const view=page.getByRole('region',{name:'All task trajectories'});
 await expect(view.locator('.trajectory-counters')).toBeVisible({timeout:90000});
 await view.getByRole('button',{name:'Fullscreen',exact:true}).click();
 await expect.poll(()=>page.evaluate(()=>Boolean(document.fullscreenElement))).toBe(true);
 const observed=await page.locator('.trajectory-playback:fullscreen').evaluate(root=>{
  const counter=root.querySelector('.trajectory-counters');
  if(!counter)throw Error('Missing visible metrics');
  const style=getComputedStyle(root);const text=getComputedStyle(counter);
  return {background:style.backgroundColor,foreground:text.color,paddingBottom:style.paddingBottom,text:counter.textContent};
 });
 const rgb=value=>{const result=value.match(/^rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)$/);assert.ok(result,value);assert.ok(!result[4]||Number(result[4])===1,value);return result.slice(1,4).map(Number);};
 const luminance=values=>values.map(v=>v/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0);
 const a=luminance(rgb(observed.foreground)),b=luminance(rgb(observed.background));
 observed.contrast=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);
 await writeFile(process.argv[2],JSON.stringify(observed,null,2)+'\n');console.log(JSON.stringify(observed));
 assert.ok(observed.contrast>=4.5,`Fullscreen metrics contrast ${observed.contrast.toFixed(2)}:1 is below 4.5:1`);
 assert.ok(Number.parseFloat(observed.paddingBottom)>=76,'Fullscreen transport must retain its reserved bottom padding');
 assert.deepEqual(errors,[]);
}finally{await browser?.close();server.kill('SIGTERM');}
